<template>
  <div class="handler">
    <!-- resize handler -->
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler w"
      :style="{
        position: 'absolute',
        cursor: 'w-resize',
        display: 'block',
        left: displayPosX(item) - 5 + 'px',
        top: displayPosY(item) + item.height / 2 - 4 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 'w')"
    ></div>
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler sw"
      :style="{
        position: 'absolute',
        cursor: 'sw-resize',
        display: 'block',
        left: displayPosX(item) - 4 + 'px',
        top: displayPosY(item) + item.height - 6 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 'sw')"
    ></div>
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler s"
      :style="{
        position: 'absolute',
        cursor: 's-resize',
        display: 'block',
        left: displayPosX(item) + item.width / 2 - 4 + 'px',
        top: displayPosY(item) + item.height - 4 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 's')"
    ></div>
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler se"
      :style="{
        position: 'absolute',
        cursor: 'se-resize',
        display: 'block',
        left: displayPosX(item) + item.width - 6 + 'px',
        top: displayPosY(item) + item.height - 6 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 'se')"
    ></div>
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler e"
      :style="{
        position: 'absolute',
        cursor: 'e-resize',
        display: 'block',
        left: displayPosX(item) + item.width - 5 + 'px',
        top: displayPosY(item) + item.height / 2 - 6 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 'e')"
    ></div>
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler ne"
      :style="{
        position: 'absolute',
        cursor: 'ne-resize',
        display: 'block',
        left: displayPosX(item) + item.width - 6 + 'px',
        top: displayPosY(item) - 4 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 'ne')"
    ></div>
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler n"
      :style="{
        position: 'absolute',
        cursor: 'n-resize',
        display: 'block',
        left: displayPosX(item) + item.width / 2 - 4 + 'px',
        top: displayPosY(item) - 4 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 'n')"
    ></div>
    <div
      v-if="item.resizable"
      class="select-areas-resize-handler nw"
      :style="{
        position: 'absolute',
        cursor: 'nw-resize',
        display: 'block',
        left: displayPosX(item) - 4 + 'px',
        top: displayPosY(item) - 4 + 'px',
        'z-index': item.z + 10,
      }"
      @mousedown.stop.prevent="startDrag(item, 'nw')"
    ></div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
export default defineComponent({
  data() {
    return {
      pos: null,
    };
  },
  props: {
    item: {
      type: Object,
      default: () => {
        return {
          id: 0,
          x: 0,
          y: 0,
          width: 0,
          height: 0,
          z: 0,
          resizable: false,
        };
      },
    },
    posCorrection: {
      type: Boolean,
      default: true,
    },
    posImg: {
      type: Object,
      default: null,
    },
  },
  methods: {
    displayPosX(item: any): any {
      return item.x + (this.posCorrection ? this.posImg.left : 0);
    },
    displayPosY(item: any): any {
      return item.y + (this.posCorrection ? this.posImg.top : 0);
    },
    startDrag(item: any, type: any) {
      this.pos = type;
      document.addEventListener('mousemove', this.doDrag);
      window.addEventListener('pointerup', this.stopDrag);
      this.$emit('startDrag');
    },
    doDrag(e: any) {
      this.$emit('doDrag', this.item, this.pos, e);
    },
    stopDrag(e: any) {
      document.removeEventListener('mousemove', this.doDrag);
    },
    removeDoDragEvent(e: any) {
      document.removeEventListener('mousemove', this.doDrag);
    },
  },
  updated() {
    if (this.item.resizable === false) {
      window.addEventListener('mouseup', this.removeDoDragEvent);
    }
  },
  unmounted: function () {
    document.removeEventListener('mousemove', this.doDrag);
    window.removeEventListener('pointerup', this.stopDrag);
    window.removeEventListener('mouseup', this.removeDoDragEvent);
  },
});
</script>
<style lang="scss" scoped>
.select-areas-resize-handler {
  background-color: $primary;
  border: 1px #fff solid;
  height: 8px;
  width: 8px;
  overflow: hidden;
}
</style>
